class Solution {
public:
    vector<int> goodIndices(string s) {
        vector<int> ans;
        for (int i = 0; i < (int)s.size(); ++i) {
            string digits = to_string(i);
            int len = digits.size();
            if (len <= i + 1 && s.compare(i + 1 - len, len, digits) == 0)
                ans.push_back(i);
        }
        return ans;
    }
};
